INSERT INTO dnd35_powers
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   discipline_id,subdiscipline,manifesting_time,action_type,range_text,target_text,area_text,effect_text,
   duration_text,save,saving_throw_text,power_resistance,power_resistance_text,power_points,
   augmentation_text,augmentation)
SELECT
  'xph-power-' || d.slug,
  'xph-3.5',
  'Chapter 5',
  d.slug,d.name,d.description,d.description,
  0,NULL,1,
  'xph-power-discipline-' || d.discipline,
  d.subdiscipline,
  d.manifesting_time,d.action_type,d.range_text,d.target_text,d.area_text,d.effect_text,
  d.duration_text,d.save,d.saving_throw_text,d.power_resistance,d.power_resistance_text,d.power_points,
  d.augmentation_text,NULL
FROM desired d
WHERE NOT EXISTS (
  SELECT 1 FROM dnd35_powers existing
  WHERE existing.slug = d.slug AND existing.owner_user_id IS NULL
);
